const $=s=>document.querySelector(s),root=document.documentElement;let selected=6;try{let n=Number(localStorage.getItem('ember-palette')??6);if(Number.isInteger(n)&&n>=0&&n<palettes.length)selected=n}catch{}
function apply(i){selected=i;const p=palettes[i],light=[11,12,13].includes(i),base=light?'#'+p[4]:'#'+p[1],text=light?'#272334':i===4?'#F5ECFA':i===5?'#F1EFF8':i===10?'#FFF1F5':'#'+p[5];const vars={base,accent:'#'+p[2],soft:'#'+p[i===4||i===5?4:3],glow:'#'+p[4],text,muted:light?'#514657':`color-mix(in srgb,${text} 76%,${base})`,surface:light?'#ffffffa8':base+'bc',border:light?'#27233428':text+'28',ink:light?'#272334':base};if(i>=14){const lightNew=[14,16,17,18,19,21].includes(i);const b=lightNew?'#'+p[i===17?2:i===19||i===21?4:1]:'#'+p[i===15?5:1];const t=lightNew?'#'+p[5]:'#'+p[i===15?4:5];Object.assign(vars,{base:b,text:t,accent:'#'+p[i===16?4:i===17?3:i===14?4:2],soft:'#'+p[i===19?2:i===22?4:3],glow:'#'+p[i===14?3:4],muted:`color-mix(in srgb,${t} 80%,${b})`,surface:lightNew?'#ffffffb8':b+'bc',border:t+'28',ink:lightNew?t:b});root.style.colorScheme=lightNew?'light':'dark'}Object.entries(vars).forEach(([k,v])=>root.style.setProperty('--'+k,v));if(i<14)root.style.colorScheme=light?'light':'dark';$('meta[name="theme-color"]').content=vars.base;$('#theme-name').textContent=p[0];$('#counter').textContent=String(i+1).padStart(2,'0')+' / '+palettes.length;document.querySelectorAll('[data-palette]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.palette===i)));try{localStorage.setItem('ember-palette',i)}catch{}}
for(const [i,p] of palettes.entries()){for(const [target,cls] of [['#swatches','swatch'],['#grid','tile']]){const b=document.createElement('button');b.className=cls;b.dataset.palette=i;b.setAttribute('aria-label',p[0]);const s=document.createElement('i');s.style.background=`linear-gradient(135deg,${p.slice(1).map(c=>'#'+c).join(',')})`;b.append(s,document.createTextNode(p[0]));b.onclick=()=>apply(i);$(target).append(b)}}apply(selected);
const modal=$('#themes');$('#show-all').onclick=$('#palette-nav').onclick=()=>modal.showModal();$('#close').onclick=()=>modal.close();modal.onclick=e=>{if(e.target===modal&&e.offsetX<0)modal.close()};let timer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}$('#add').onclick=()=>toast('Це тест палітр. Записи харчування тут не зберігаються.');$('#summary').onclick=()=>toast('Показники демонстраційні — порівнюй вигляд тем.');$('#about').onclick=()=>toast('23 палітри · вибір зберігається в цьому браузері.');$('#home').onclick=()=>window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});$('#motion').onclick=()=>{const paused=document.body.classList.toggle('paused');$('#motion').setAttribute('aria-pressed',paused);$('#motion').setAttribute('aria-label',paused?'Відновити анімацію':'Призупинити анімацію');$('#motion').textContent=paused?'▷':'Ⅱ'};
for(let i=0;i<20;i++){let x=i*53-160;const d=`M ${x} -50 C ${x+290} 180,${x-200} 290,${x+180} 500 S ${x+60} 840,${x+270} 1100`;for(const cls of ['fibre','impulse']){const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',d);path.setAttribute('class',cls);path.style.animationDelay=(-i*1.7)+'s';$('#fibres').append(path)}}

const modes=[['neural','Нейрони'],['aurora','Сяйво'],['waves','Хвилі'],['pulse','Пульс'],['dust','Частинки'],['still','Без руху']];
let currentMode='neural';try{const saved=localStorage.getItem('ember-motion');if(modes.some(m=>m[0]===saved))currentMode=saved}catch{}
function setMode(mode){currentMode=mode;document.body.dataset.animation=mode;document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));$('#animation-note').textContent=mode==='pulse'?'Художній ритм · не показник пульсу':mode==='still'?'Спокійний градієнт без руху':'Поєднуй будь-яку анімацію з будь-якою палітрою';try{localStorage.setItem('ember-motion',mode)}catch{}}
for(const [id,name] of modes){const b=document.createElement('button');b.dataset.mode=id;b.textContent=name;b.onclick=()=>setMode(id);$('#animations').append(b)}setMode(currentMode);
const bg=$('.ambient');const wave=document.createElement('div');wave.className='wave-field';for(let i=0;i<7;i++){const el=document.createElement('i');el.style.setProperty('--i',i);wave.append(el)}bg.append(wave);
const pulses=document.createElement('div');pulses.className='pulse-field';for(let i=0;i<4;i++){const el=document.createElement('i');el.style.animationDelay=(-i*2)+'s';pulses.append(el)}bg.append(pulses);
const dust=document.createElement('div');dust.className='dust-field';for(let i=0;i<32;i++){const el=document.createElement('i');el.style.cssText=`left:${(i*37)%100}%;top:${(i*23)%100}%;width:${2+i%4}px;height:${2+i%4}px;animation-delay:-${i*1.7}s;animation-duration:${14+i%9}s`;dust.append(el)}bg.append(dust);
